#include <stdio.h>
#include <string.h>

void swap(char s[],int j,int n)
    {
        char temp;
        temp=s[j];
        s[j]=s[n];
        s[n]=temp;
    }

void permute(char s[],int m,int n)
{
    int j;

    if(m==(n-1))
        printf("%s\n",s);

    for(j=m;j<n;j++)
    {        
        swap(s,j,n-1);
        permute(s,m+1,n);
        swap(s,j,n-1);
    }

}
